typedef unsigned char u_char;
typedef unsigned int u_int;
typedef unsigned int u_long128 __attribute__((mode(TI)));

struct sceIpuDmaEnv {
    u_int d4madr;
    u_int d4tadr;
    u_int d4qwc;
    u_int d4chcr;
    u_int d3madr;
    u_int d3qwc;
    u_int d3chcr;
    u_int ipubp;
    u_int ipuctrl;
};

struct TimeStamp {
    long pts;
    long dts;
    int pos;
    int len;
};

typedef struct {
    u_long128 *data;
    u_long128 *tag;
    int n;
    int dmaStart;
    int dmaN;
    int readBytes;
    int buffSize;
    sceIpuDmaEnv env;
    int sema;
    int isActive;
    long totalBytes;
    TimeStamp *ts;
    int n_ts;
    int count_ts;
    int wt_ts;
} ViBuf;

extern "C" int WaitSema(int sema);
extern "C" int SignalSema(int sema);

__asm__(".equ WaitSema, 0x003DB6A0");
__asm__(".equ SignalSema, 0x003DB680");

#define NULL 0
#define VIBUF_ELM_SIZE 2048
#define REST 2
#define FS(f) ((f->dmaStart+f->dmaN)*VIBUF_ELM_SIZE)
#define FN(f) ((f->n-REST-f->dmaN)*VIBUF_ELM_SIZE)

static void viBufBeginPut( ViBuf *f, u_char **ptr0, int *len0, u_char **ptr1, int *len1 )
{
    int es, en, fs, fn;

    WaitSema( f->sema );
    fs = FS( f );
    fn = FN( f );
    es = ( fs + f->readBytes ) % f->buffSize;
    en = fn - f->readBytes;
    if( f->buffSize - es >= en )
    {
        *ptr0 = (u_char*)f->data + es;
        *len0 = en;
        *ptr1 = NULL;
        *len1 = 0;
    }
    else
    {
        *ptr0 = (u_char*)f->data + es;
        *len0 = f->buffSize - es;
        *ptr1 = (u_char*)f->data;
        *len1 = en - (f->buffSize - es);
    }
    SignalSema(f->sema);
}
